<script setup lang="ts">
import type {World,Language} from '../../../packages/shared/src/types';
import {computed,ref} from 'vue';
import {bagWeight,itemWeight} from '../../../packages/engine/src/chapters';
import {keepsakeView} from '../../../packages/engine/src/keepsakes';
import {uniformAsset} from '../../../packages/world-data/src/uniforms';
const viewed=ref<string|null>(null);
const props=defineProps<{state:World;lang:Language;memorialOnly?:boolean}>();defineEmits<{discard:[id:string]}>();const p=computed(()=>props.state.people.find(n=>n.id===props.state.playerId)!);
const view=(id:string)=>keepsakeView(props.state,p.value,id,props.lang);
const uniform=(id:string)=>{const parts=id.split(':');return uniformAsset(p.value.enrollments.find(e=>e.level===parts[1]&&e.startYear===Number(parts[2]))?.schoolId,p.value.gender,parts[1]);};
</script>
<template><section class="belongings"><h1 v-if="!memorialOnly">{{lang==='zh'?'隨身的回憶':'Keepsakes'}}</h1><p>{{bagWeight(p)}} g · {{lang==='zh'?'不限容量':'Unlimited capacity'}}</p><div v-if="!memorialOnly" class="keepsake-grid"><article v-for="(id,i) in p.inventory" :key="id+':'+i"><div class="keepsake-art"><img v-if="id.includes('uniform')" :src="uniform(id)" :alt="view(id).title" class="uniform-art"><svg v-else viewBox="0 0 100 90" aria-hidden="true"><rect x="3" y="3" width="94" height="84" rx="16" fill="#e4eedf"/><g v-if="id.includes('uniform')" stroke="#465c66" stroke-width="3" fill="#fffaf0"><path d="M32 18 12 35 25 51 32 44 32 76 68 76 68 44 75 51 88 35 68 18 58 24 42 24Z"/><path d="M42 24 50 40 58 24M50 40V76"/></g><g v-else-if="id.includes('clover')" fill="#56966c"><circle cx="42" cy="33" r="14"/><circle cx="62" cy="33" r="14"/><circle cx="42" cy="52" r="14"/><circle cx="62" cy="52" r="14"/><path d="M50 45 62 78" stroke="#377249" stroke-width="4"/></g><g v-else-if="id==='blanket'"><path d="M20 20H72L82 72H26Z" fill="#e9b9b3" stroke="#b2777b" stroke-width="3"/><path d="M28 38H74M30 52H77" stroke="#fff3e6" stroke-width="4"/></g><g v-else-if="id.startsWith('instrument:')" fill="#cd996b" stroke="#815f51" stroke-width="3"><path d="M45 15H55V40C78 40 78 76 50 77C22 76 22 40 45 40Z"/><path d="M50 17V69M43 60H57"/><circle cx="50" cy="48" r="4" fill="#594b45"/></g><g v-else-if="id.startsWith('sport:')" stroke="#a26d3e" stroke-width="3"><circle cx="50" cy="46" r="29" fill="#f2bc74"/><path d="M21 46H79M50 17V75M30 24Q60 46 30 68M70 24Q40 46 70 68" fill="none"/></g><g v-else-if="id.includes('card')" stroke="#b6808c" stroke-width="3"><rect x="17" y="23" width="66" height="46" rx="6" fill="#fff8ee"/><path d="M18 25 50 49 82 25" fill="none"/><path d="M39 42C30 29 48 27 50 35C57 24 72 35 61 44L50 54Z" fill="#e8a3ad"/></g><g v-else-if="id.startsWith('photo:')" stroke="#6b9983" stroke-width="3"><rect x="19" y="16" width="62" height="62" fill="#fff9ed"/><path d="M24 61 42 37 56 52 66 41 76 61Z" fill="#9dc4a1"/><circle cx="66" cy="30" r="7" fill="#efca7a"/></g><g v-else-if="id==='stickers'" stroke="#d5aa61" stroke-width="3"><path d="M50 15 59 34 80 37 65 53 69 75 50 65 31 75 35 53 20 37 41 34Z" fill="#ffe3a2"/><circle cx="43" cy="45" r="2"/><circle cx="58" cy="45" r="2"/><path d="M44 55Q50 61 57 55" fill="none"/></g><g v-else><rect x="24" y="18" width="52" height="58" rx="6" fill="#f4cf86" stroke="#aa8b61" stroke-width="3"/><path d="M34 34H65M34 45H60M34 56H65" stroke="#fff8e7" stroke-width="4"/></g></svg></div><b class="keepsake-title">{{view(id).title}}</b><small class="keepsake-weight">{{itemWeight(id)}} g</small><div class="keepsake-actions"><button class="inspect-item" @click="viewed=id">{{lang==='zh'?'檢視':'Inspect'}}</button><button v-if="state.phase!=='dead'" @click="$emit('discard',id)">{{lang==='zh'?'放下這件物品':'Let this item go'}}</button></div></article></div><div v-if="state.phase==='dead'" class="life-keepsake-card"><h2>{{p.name}} · {{lang==='zh'?'留下的溫柔':'What remains'}}</h2><p>{{state.reports.filter(r=>r.personId===p.id).at(-1)?.summary[lang]}}</p><p>{{lang==='zh'?`走過 ${state.year-p.birthYear} 年，留下 ${p.children.length} 位孩子的牽掛，和 ${p.inventory.length} 件帶著故事的物品。`:`A life of ${state.year-p.birthYear} years, with ${p.inventory.length} keepsakes.`}}</p><span v-for="id in p.inventory.slice(0,12)" :key="id">❀ {{view(id).title}} </span></div><div v-if="viewed" class="dialog-backdrop" @click.self="viewed=null"><section role="dialog" aria-modal="true" :aria-label="view(viewed).title" class="setup-dialog"><button class="close-dialog" @click="viewed=null" :aria-label="lang==='zh'?'關閉道具檢視':'Close item'">×</button><h2>{{view(viewed).title}}</h2><img v-if="viewed.includes('uniform')" :src="uniform(viewed)" :alt="view(viewed).title" class="uniform-art"><p class="narrative">{{view(viewed).description}}</p><button @click="viewed=null">{{lang==='zh'?'好好收起來':'Put it away'}}</button></section></div></section></template>
